<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { route as routeSource,go,setQuery,back } from '../workbench/navigation';
import { userMock,userRoles,findAccount,relationsFor,accountSpaces,visibleSpaces,createAccount,renameAccount,linkAccounts,unlinkAccounts,recoverAccount,type MockAccount } from '../workbench/user-management-mock';
import WorkbenchDialog from './WorkbenchDialog.vue';
import PagingBar from './PagingBar.vue';
const route=routeSource,location=window.location;
const current=computed(()=>findAccount(route.id));
const activeRelations=(a:MockAccount)=>relationsFor(a.id).filter(r=>r.active);
const filtered=computed(()=>userMock.accounts.filter(a=>(!route.filter||a.role===route.filter)&&(!route.status||(a.role!=='admin'&&(route.status==='linked'?activeRelations(a).length>0:route.status==='unlinked'?activeRelations(a).length===0:false)))&&`${a.name} ${a.login} ${a.id} ${a.learnerId}`.toLowerCase().includes(route.q.trim().toLowerCase())).sort((a,b)=>route.sort==='name'?a.name.localeCompare(b.name,'zh-CN'):b.createdAt.localeCompare(a.createdAt)||a.id.localeCompare(b.id)));
const page=computed(()=>Math.min(route.p,Math.max(1,Math.ceil(filtered.value.length/10))));
const tabs=computed(()=>current.value?.role==='admin'?{profile:'基本信息',history:'操作记录'}:{profile:'基本信息',relations:'亲子关系',learning:'学习关联',confirmations:'首次确认',history:'操作记录'});
const tab=computed(()=>Object.prototype.hasOwnProperty.call(tabs.value,route.tab)?route.tab:'profile');
const showEnded=ref(false);
const relations=computed(()=>current.value?relationsFor(current.value.id).filter(r=>showEnded.value||r.active).sort((a,b)=>Number(b.active)-Number(a.active)||b.updatedAt.localeCompare(a.updatedAt)):[]);
const history=computed(()=>userMock.operations.filter(o=>o.accountIds.includes(route.id)).sort((a,b)=>b.at.localeCompare(a.at)));
const historyPage=computed(()=>Math.min(route.p,Math.max(1,Math.ceil(history.value.length/10))));
const confirmations=computed(()=>current.value?.role==='parent'?userMock.confirmations.filter(c=>confirmedStudents.value.includes(c.studentId)&&(c.accountId===route.id||c.accountId===c.studentId)):userMock.confirmations.filter(c=>c.studentId===route.id));
const confirmedStudents=computed(()=>current.value?.role==='parent'?[...new Set(relationsFor(route.id).map(r=>r.studentId))]:[route.id]);
const spaces=computed(()=>current.value?visibleSpaces(current.value):[]);
const relationSummary=(a:MockAccount)=>a.role==='admin'?'独立管理身份':activeRelations(a).length+' 名有效关联'+(a.role==='student'?'家长':'孩子');
const name=(id:string)=>findAccount(id)?.name||id;
function open(id:string){go('users',{id,returnTo:location.hash});}
function openSpace(id:string){go('learning-spaces',{id,returnTo:location.hash});}
function openState(a:MockAccount){go('students',{id:a.learnerId,returnTo:location.hash});}
function reset(){setQuery({q:'',filter:'',status:'',sort:'',p:1});}
const modal=ref<''|'create'|'rename'|'link'|'unlink'|'recover'>(''),error=ref(''),notice=ref('');
const form=ref({role:'student' as 'student'|'parent',name:'',login:'',reason:'',verified:false});
const query=ref(''),selectedId=ref(''),relationId=ref('');
const relation=computed(()=>userMock.relations.find(r=>r.id===relationId.value));
const candidateRole=computed(()=>current.value?.role==='student'?'parent':'student');
const candidates=computed(()=>query.value.trim()?userMock.accounts.filter(a=>a.role===candidateRole.value&&`${a.name} ${a.login} ${a.id} ${a.learnerId}`.toLowerCase().includes(query.value.trim().toLowerCase())):[]);
const selected=computed(()=>candidates.value.find(a=>a.id===selectedId.value));
const pair=(id:string)=>({parentId:current.value?.role==='parent'?route.id:id,studentId:current.value?.role==='student'?route.id:id});
const existing=(id:string)=>{const p=pair(id);return userMock.relations.find(r=>r.parentId===p.parentId&&r.studentId===p.studentId);};
watch(query,()=>{selectedId.value='';error.value='';});
watch(()=>route.id,()=>{modal.value='';error.value='';showEnded.value=false;});
function start(action:typeof modal.value,relationKey=''){
  form.value={role:'student',name:current.value?.name||'',login:'',reason:'',verified:false};query.value='';selectedId.value='';relationId.value=relationKey;error.value='';notice.value='';modal.value=action;
}
const modalTitle=computed(()=>({create:'新增账号',rename:'编辑显示名称',link:'建立亲子关联',unlink:'解除亲子关联',recover:'找回原账号','':''})[modal.value]);
function save(){
  error.value='';try{
    if(modal.value==='create'){const a=createAccount(form.value.role,form.value.name,form.value.login,form.value.verified,form.value.reason);modal.value='';notice.value='已建立 mock 账号；尚未建立亲子关系或学习空间。';go('users',{id:a.id,returnTo:location.hash});return;}
    if(!current.value)throw Error('账号不存在，请返回列表重新选择。');
    if(modal.value==='rename')renameAccount(route.id,form.value.name,form.value.reason);
    else if(modal.value==='link'){if(!selected.value)throw Error('请搜索并明确选择要关联的账号。');const p=pair(selected.value.id);linkAccounts(p.parentId,p.studentId,form.value.verified,form.value.reason);}
    else if(modal.value==='unlink')unlinkAccounts(relationId.value,form.value.verified,form.value.reason);
    else if(modal.value==='recover')recoverAccount(route.id,form.value.verified,form.value.reason);
    notice.value=modal.value==='recover'?'已记录本次 mock 找回，原账号、学习者及学习记录保持；没有执行真实密码重置。':'已保存本次 mock 操作，操作记录可追溯。';
    modal.value='';
  }catch(e){error.value=e instanceof Error?e.message:String(e);}
}
</script>
<template><div class="wb-page user-management">
  <header class="page-header user-header"><div><button v-if="route.id" class="text-link" @click="back('users')">← {{route.returnTo.startsWith('#/users?')&&route.returnTo.includes('id=')?'返回来源账号':'返回账号列表'}}</button><h2>{{!route.id?'用户管理':current?current.name:'未找到账号'}}</h2><p class="page-desc">{{!route.id?'维护独立账号、亲子关系和找回记录；学习情况从对应学生与空间查看。':current?userRoles[current.role]+' · '+current.login+' · '+current.id:'未知标识不会映射到同名账号。'}}</p></div><button v-if="!route.id" class="btn primary" @click="start('create')">新增账号</button><span v-else class="badge">Mock · 账号与关系</span></header>
  <p v-if="notice" class="callout green" role="status">{{notice}}</p>
  <section v-if="route.id&&!current" class="panel"><p role="alert">所选账号不存在。旧版 ST-* 身份与当前账号不按名称自动合并。</p><button class="btn" @click="go('users')">返回账号列表</button></section>
  <template v-else-if="!route.id">
    <section class="metric-grid user-metrics"><button class="metric-card" @click="setQuery({filter:'',p:1})"><span>已建档账号</span><strong>{{userMock.accounts.length}}</strong><small>全部 mock 账号，不是活跃人数</small></button><button v-for="(label,role) in userRoles" :key="role" class="metric-card" @click="setQuery({filter:role,status:'',p:1})"><span>{{label}}</span><strong>{{userMock.accounts.filter(a=>a.role===role).length}}</strong><small>{{role==='student'?'包含尚未创建空间的学生':role==='parent'?'独立账号，逐条关联孩子':'初始化的管理身份'}}</small></button></section>
    <div class="toolbar user-filters"><label class="search-label">查找账号<input type="search" :value="route.q" placeholder="姓名、账号名或稳定标识" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})"/></label><label>角色<select aria-label="角色筛选" :value="route.filter" @change="setQuery({filter:($event.target as HTMLSelectElement).value,status:'',p:1})"><option value="">全部角色</option><option v-for="(label,key) in userRoles" :key="key" :value="key">{{label}}</option></select></label><label>亲子关联<select aria-label="关联筛选" :value="route.status" @change="setQuery({status:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部</option><option value="linked">有有效关联</option><option value="unlinked">无有效关联（学生／家长）</option></select></label><label>排序<select aria-label="账号排序" :value="route.sort||'created'" @change="setQuery({sort:($event.target as HTMLSelectElement).value,p:1})"><option value="created">最近建档优先</option><option value="name">姓名</option></select></label><button class="btn" @click="reset">重置筛选</button></div>
    <p class="muted">共 {{filtered.length}} 个符合条件的账号；上方数量为全体示例。已建档、亲子关联和首次确认分别记录，不合并为“活跃”。</p>
    <section class="table-card user-table"><table class="data-table"><thead><tr><th>姓名 / 账号名</th><th>角色</th><th>账号与学习者标识</th><th>关联摘要</th><th>账号状态</th><th></th></tr></thead><tbody><tr v-for="a in filtered.slice((page-1)*10,page*10)" :key="a.id"><td><button class="text-link user-name" @click="open(a.id)">{{a.name}}</button><small>{{a.login}}</small></td><td><span class="badge">{{userRoles[a.role]}}</span></td><td>{{a.id}}<small v-if="a.learnerId">{{a.learnerId}}</small></td><td>{{relationSummary(a)}}<small v-if="a.role==='student'">{{accountSpaces(a).length}} 个学习空间</small></td><td>已建档<small>登录与凭据为 mock</small></td><td><button class="text-link" :aria-label="'查看账号 '+a.id" @click="open(a.id)">查看详情 →</button></td></tr></tbody></table><p v-if="!filtered.length" class="empty">没有符合条件的账号。</p></section><PagingBar v-if="filtered.length>10" :total="filtered.length" :page="page"/>
  </template>
  <template v-else-if="current">
    <div class="account-summary"><span class="badge">已建档</span><span>{{relationSummary(current)}}</span><span v-if="current.learnerId">学习者 {{current.learnerId}}</span><div class="button-row"><button v-if="current.role!=='admin'" class="btn primary" @click="start('link')">{{current.role==='student'?'关联家长':'关联孩子'}}</button><button class="btn" @click="start('recover')">找回原账号</button></div></div>
    <nav class="tabs" role="tablist" aria-label="账号详情"><button v-for="(label,key) in tabs" :key="key" role="tab" :aria-selected="tab===key" :class="{active:tab===key}" @click="setQuery({tab:key,p:1})">{{label}}</button></nav>
    <section v-if="tab==='profile'" class="panel account-profile"><div class="section-heading"><h3>基本信息</h3><button class="text-link" @click="start('rename')">编辑显示名称</button></div><dl class="field-list"><dt>姓名 / 显示名称</dt><dd>{{current.name}}</dd><dt>账号名</dt><dd>{{current.login}}</dd><dt>账号标识</dt><dd>{{current.id}}</dd><dt>角色与客户端</dt><dd>{{current.role==='student'?'学生 · 学生 Android 客户端':current.role==='parent'?'家长 · 家长 Android 客户端':'管理员 · 电脑后台'}}<small>角色保持固定；家长和管理员即使是同一现实成年人，也分别登录、分别记录操作。</small></dd><template v-if="current.learnerId"><dt>对应学习者</dt><dd>{{current.learnerId}}<small>重装、换设备与找回不会创建新学习者。</small></dd></template><dt>建档时间</dt><dd>{{current.createdAt}}</dd><dt>凭据记录</dt><dd>v{{current.credentialVersion}} · Mock 版本，不含真实密码</dd><dt>最近登录</dt><dd>{{current.lastLogin||'未记录；不以最近学习日期代替'}}</dd></dl><p class="muted">账号管理不维护能力分数，不修改个人 Belief。{{current.role==='admin'?'本账号由部署初始化；找回不依赖家长身份或另一名管理员。':''}}</p></section>
    <section v-else-if="tab==='relations'" class="panel account-relations"><div class="section-heading"><h3>{{current.role==='student'?'关联家长':'关联孩子'}}</h3><label class="check-label"><input type="checkbox" v-model="showEnded"/>包含已解除关系</label></div><p class="muted">每段关系独立有效。同一孩子可以关联多位家长，一位家长可以关联多个孩子。</p><div class="scroll-table"><table class="data-table"><thead><tr><th>关联账号</th><th>状态 / 范围</th><th>核实与最近操作</th><th></th></tr></thead><tbody><tr v-for="r in relations" :key="r.id"><td><button class="text-link" @click="open(current.role==='student'?r.parentId:r.studentId)">{{name(current.role==='student'?r.parentId:r.studentId)}}</button><small>{{current.role==='student'?r.parentId:r.studentId}}</small><small>{{r.id}}</small></td><td><span class="badge" :class="{green:r.active}">{{r.active?'关联有效':'已解除'}}</span><p>{{r.scope}}</p></td><td>核实：{{r.verifiedAt}}<small>最近操作：{{r.updatedAt}}</small><small>{{r.reason}}</small></td><td><button v-if="r.active" class="text-link" :aria-label="'解除关联 '+r.id" @click="start('unlink',r.id)">解除关联</button><span v-else class="muted">重新搜索关联并核实可恢复</span></td></tr></tbody></table></div><p v-if="!relations.length" class="empty">暂无{{showEnded?'':'有效'}}亲子关联。开户不会自动建立关联。</p><p class="muted">家长关联只授予规定范围内的查看与咨询，不授予代作答、修改孩子资料、创建课程或管理权限。</p></section>
    <section v-else-if="tab==='learning'" class="panel account-learning"><h3>{{current.role==='student'?'所属学习空间':'有效关联下可查看的学习空间'}}</h3><p class="muted">{{current.role==='student'?'学习空间由学生端创建；后台开户不代建课程，也不替学生选择目标。':'以下入口以管理员身份查阅关联范围，不是登录或冒充家长。已解除关系不再提供相应孩子的空间入口。'}}</p><div class="scroll-table"><table class="data-table"><thead><tr><th>学生</th><th>学习空间</th><th>教材 / 学习目标</th><th></th></tr></thead><tbody><tr v-for="s in spaces" :key="s.id"><td>{{s.studentName}}<small>{{s.studentId}}</small></td><td>{{s.name}}<small>{{s.id}}</small></td><td>{{s.adopted.book.name}}<small>{{s.adopted.target.name}}</small></td><td><button class="text-link" :aria-label="'查看空间 '+s.id" @click="openSpace(s.id)">学习空间 →</button><button class="text-link" :aria-label="'查看学生状态 '+s.id" @click="go('students',{id:s.studentId,scope:s.id,returnTo:location.hash})">学生状态 →</button></td></tr></tbody></table></div><p v-if="!spaces.length" class="empty">{{current.role==='student'?'该学习者尚未创建学习空间，尚无课程能力判断。账号仍保留在用户目录。':'暂无有效关联下的学习空间；未关联或孩子尚未创建空间都可能出现此情况。'}}</p><button v-if="current.role==='student'&&spaces.length" class="text-link" @click="openState(current)">查看该学生全部空间的状态 →</button><p v-if="current.role==='parent'" class="callout">本页使用新的后台关系示例。旧家长客户端的独立示例身份尚未映射，不按同名合并，不据此声称客户端权限已经接通。</p></section>
    <section v-else-if="tab==='confirmations'" class="panel account-confirmations"><h3>首次说明与确认记录</h3><p>查看家长对说明的确认和孩子的参与确认。开户、有效亲子关系和管理员核实都不能替代本人确认。</p><div class="scroll-table"><table class="data-table"><thead><tr><th>孩子 / 确认人</th><th>记录类型</th><th>记录状态</th><th>说明版本 / 时间</th></tr></thead><tbody><template v-for="studentId in confirmedStudents" :key="studentId"><tr><td>{{name(studentId)}}<small>{{studentId}}</small></td><td>孩子参与确认</td><td>{{confirmations.some(c=>c.accountId===studentId&&c.type==='participation')?'已记录（示例）':'尚未记录'}}</td><td>{{confirmations.find(c=>c.accountId===studentId&&c.type==='participation')?.version||'—'}}<small>{{confirmations.find(c=>c.accountId===studentId&&c.type==='participation')?.at||'—'}}</small></td></tr><tr v-for="r in relationsFor(studentId).filter(r=>current!.role==='student'||r.parentId===current!.id)" :key="r.id"><td>{{name(studentId)}} / {{name(r.parentId)}}<small>{{r.parentId}}</small></td><td>家长说明确认<small>{{r.active?'关联有效':'关联已解除；仅保留历史记录'}}</small></td><td>{{confirmations.some(c=>c.accountId===r.parentId&&c.studentId===studentId&&c.type==='notice')?'已记录（示例）':'尚未记录'}}</td><td>{{confirmations.find(c=>c.accountId===r.parentId&&c.studentId===studentId&&c.type==='notice')?.version||'—'}}<small>{{confirmations.find(c=>c.accountId===r.parentId&&c.studentId===studentId&&c.type==='notice')?.at||'—'}}</small></td></tr></template></tbody></table></div><p v-if="!confirmedStudents.length" class="empty">尚无关联孩子的确认记录。</p><p class="muted">MOCK-NOTICE-1 仅用于合成材料演示，不代表真实服务的授权。逐人保留记录，不从某一人的确认推断其他人已经确认；管理员不能在此代为确认。</p></section>
    <section v-else-if="tab==='history'" class="table-card account-history"><table class="data-table"><thead><tr><th>时间 / 操作</th><th>操作者</th><th>依据</th><th>结果与关联</th></tr></thead><tbody><tr v-for="o in history.slice((historyPage-1)*10,historyPage*10)" :key="o.id"><td>{{o.at}}<small>{{o.action}}</small></td><td>{{name(o.actor)}}<small>{{o.actor}}</small></td><td>{{o.reason}}</td><td>{{o.detail}}<small>{{o.id}}</small><button v-for="id in o.accountIds.filter(id=>id!==current!.id)" :key="id" class="text-link" @click="open(id)">{{name(id)}} →</button></td></tr></tbody></table><p v-if="!history.length" class="empty">暂无操作记录。</p><PagingBar v-if="history.length>10" :total="history.length" :page="historyPage"/></section>
  </template>
  <details class="account-boundaries"><summary>账号与关系示例边界</summary><p>当前账号与 LEARNER-A、LEARNER-B 及其 SPACE-* 空间明确关联。学生 C 和本次新建学生没有课程；旧 ST-* 账号和旧家长端记录不自动迁移。</p><p>只在本页维护 mock 账号、关联及操作记录，刷新恢复初始示例。未接入真实登录、密码发放、跨端撤权或正式首次授权，不采集真实密码、证件或同意凭据。初始管理员独立展示，本轮不增加禁用、角色转换或增设管理员流程。</p></details>
  <WorkbenchDialog v-if="modal" :title="modalTitle" :wide="modal==='link'" @close="modal=''">
    <form @submit.prevent="save">
      <template v-if="modal==='create'"><label>账号角色<select aria-label="账号角色" v-model="form.role"><option value="student">学生</option><option value="parent">家长</option></select></label><label>姓名 / 显示名称<input aria-label="姓名或显示名称" v-model="form.name" maxlength="60"/></label><label>账号名<input aria-label="账号名" v-model="form.login" maxlength="40" autocomplete="off" placeholder="3–40 个字符，不含空白"/></label><p class="muted">账号独立建立，不自动关联或创建学习空间。无需学生手机号、邮箱或证件上传；首个管理员由部署初始化。</p></template>
      <template v-else-if="modal==='rename'"><p>{{current?.login}} · {{current?.id}}</p><label>姓名 / 显示名称<input aria-label="姓名或显示名称" v-model="form.name" maxlength="60"/></label><p class="muted">只修改显示名称；当前课程中的学生显示名称同步更新，账号、角色、学习者及历史归属保持。</p></template>
      <template v-else-if="modal==='link'"><p><strong>{{current?.name}}</strong> · {{current?.login}} · {{current?.id}}</p><label>查找{{candidateRole==='parent'?'家长':'学生'}}账号<input aria-label="查找关联账号" type="search" v-model="query" placeholder="输入姓名、账号名或标识"/></label><p v-if="!query.trim()" class="muted">先搜索，再核对具体账号；不会按同名自动关联。</p><div v-else class="candidate-list"><div v-for="a in candidates.slice(0,5)" :key="a.id" class="candidate-row"><label class="check-label"><input type="radio" name="candidate" :value="a.id" v-model="selectedId" :disabled="existing(a.id)?.active" :aria-label="'选择账号 '+a.id"/><span><strong>{{a.name}}</strong><small>{{a.login}} · {{a.id}}<template v-if="a.learnerId"> · {{a.learnerId}}</template></small></span></label><span class="muted">{{existing(a.id)?.active?'已关联':existing(a.id)?'已解除，可重新核实后关联':''}}</span></div><p v-if="!candidates.length" class="empty">未找到对应角色的账号，请先开户或调整搜索。</p><p v-if="candidates.length>5" class="muted">共 {{candidates.length}} 项，先显示 5 项；请细化账号名或标识。</p></div><p v-if="selected" class="callout">确认关联：{{current?.role==='parent'?current?.name:selected.name}} → {{current?.role==='student'?current?.name:selected.name}}。可按规则查看该孩子的学习空间及相关资料，不授予修改资料、代作答或管理权限。</p></template>
      <template v-else-if="modal==='unlink'&&relation"><p><strong>{{name(relation.parentId)}} → {{name(relation.studentId)}}</strong></p><p>解除的是这一段关系。该家长将不再通过此关联查看该孩子的资料；其他家长、其他孩子的有效关联不受影响。</p><p>原账号、学习空间、作答及评价记录保留，不删除、不转移，也不把解除关联解释成能力变化。</p><p class="muted">本轮只走查后台 mock 关系变化，未对旧家长客户端执行真实撤权。</p></template>
      <template v-else-if="modal==='recover'"><p><strong>{{current?.name}}</strong> · {{current?.login}}</p><dl class="field-list"><dt>原账号</dt><dd>{{current?.id}}</dd><dt v-if="current?.learnerId">原学习者</dt><dd v-if="current?.learnerId">{{current.learnerId}}</dd><dt>本次结果</dt><dd>凭据记录 v{{current?.credentialVersion}} → v{{(current?.credentialVersion||0)+1}}</dd></dl><p>在原账号上记录找回，亲子关联、学习空间、学习记录与首次确认记录保持。不会新增账号或学习者。</p><p v-if="current?.role==='admin'" class="callout">须在系统外核实本人及管理身份，不能依据家长关联恢复管理权，也不要求另一位管理员协助。</p><p class="muted">没有真实密码重置或设备会话处理，请勿输入密码。</p></template>
      <label v-if="modal!=='rename'" class="check-label"><input type="checkbox" v-model="form.verified"/>已完成本次操作所需的系统外核实</label><label>{{modal==='rename'?'修改原因':'核实依据'}}<textarea :aria-label="modal==='rename'?'修改原因':'核实依据'" v-model="form.reason" maxlength="1000" placeholder="记录核实方式和结论，仅填写示例，不录入真实敏感资料。"/></label>
      <p v-if="error" class="callout danger" role="alert">{{error}}</p><div class="dialog-footer button-row"><button type="button" class="btn" @click="modal=''">取消</button><button type="submit" class="btn primary">{{modal==='create'?'确认开户':modal==='link'?'保存关联':modal==='unlink'?'确认解除':modal==='recover'?'记录找回':'保存'}}</button></div>
    </form>
  </WorkbenchDialog>
</div></template>
